import pyparsing as pp
from ta_emil_cli_aatrace_parser.aashell_user import execute_aashell_command
from ta_emil_cli_aatrace_parser.tracecollector import TraceCollector

NODES_CMD = "nodes -p"


COLON = pp.Suppress(pp.Literal(":"))
COMMA = pp.Suppress(pp.Literal(","))
HASH = pp.Suppress(pp.Literal("#"))
HYPHEN = pp.Suppress(pp.Literal("-"))

NODE_STR = pp.Literal("node")
CE_NAME_STR = pp.Literal("ceName")
OWN_N_ID_STR = pp.Literal("ownNid")
MASTER_N_ID_STR = pp.Literal("masterNid")
RUNNING_PROCESSES_STR = pp.Literal("Running processes")
NOT_SET_STR = pp.Literal("NOT SET")
PROCESS_NAME = pp.Word(pp.alphanums)
NODE_ID = pp.Word(pp.hexnums + "x")

NODE = pp.Group(NODE_STR + COLON + NODE_ID)
CE_NAME = pp.Group(CE_NAME_STR + COLON + NOT_SET_STR)
OWN_N_ID = pp.Group(OWN_N_ID_STR + COLON + NODE_ID)
MASTER_N_ID = pp.Group(MASTER_N_ID_STR + COLON + NODE_ID)

NODE_LINE = pp.OneOrMore(HYPHEN) + NODE + pp.OneOrMore(HYPHEN)
CE_OWN_MASTER_LINE = CE_NAME + COMMA + OWN_N_ID + COMMA + MASTER_N_ID
RUNNING_PROCESSES_LINE = RUNNING_PROCESSES_STR + COLON
HASH_LINE = pp.OneOrMore(HASH)
HYPHEN_LINE = pp.OneOrMore(HYPHEN)

SINGLE_NODE = (
    NODE_LINE
    + HASH_LINE
    + CE_OWN_MASTER_LINE
    + HYPHEN_LINE
    + pp.Group(
        RUNNING_PROCESSES_LINE + HYPHEN_LINE + pp.Group(pp.OneOrMore(PROCESS_NAME))
    )
)

ALL_NODES = pp.OneOrMore(pp.Group(SINGLE_NODE))


def get_cell_mapping():
    """to be created"""
    return TraceCollector.get_platform_info_from_aashell()


def get_running_nodes_details():
    """to be created"""
    raw_output = execute_aashell_command(NODES_CMD)
    parsed_nodes_details = _parse_nodes_details(raw_output)
    return parsed_nodes_details


def get_master_node_address():
    """to be created"""
    pass


def _parse_nodes_details(raw_output):
    parsed = ALL_NODES.parseString(raw_output)
    all_nodes = []
    for node_config_list in parsed:
        node = {}
        for key, value in node_config_list:
            try:
                node[key] = value.asList()
            except AttributeError:
                node[key] = value
        all_nodes.append(node)
    return all_nodes
